ml-one-hot.solution:
import numpy as np

def one_hot(train_values, test_values):
    cats = sorted(set(train_values))
    pos = {c: i for i, c in enumerate(cats)}
    M = np.zeros((len(test_values), len(cats)), dtype=int)
    for r, v in enumerate(test_values):
        if v in pos:
            M[r, pos[v]] = 1
    return [cats, M.tolist()]

